<div class="modal-content"><div class="modal-header"><button type="button" class="close" data-dismiss="modal" aria-hidden="true">×</button><h4 class="modal-title">CREATE NEW USER</h4></div><div class="modal-body"><div id="ad-new-user-message"></div><div class="ad-wizard-grid two"><div class="ad-field"><label>Staff ID</label><input id="ad-new-user-staff" type="number" min="1" placeholder="Linked staff ID"></div><div class="ad-field"><label>Username</label><input id="ad-new-user-name" required></div><div class="ad-field"><label>User role</label><select id="ad-new-user-role"><option value="">Loading roles...</option></select></div><div class="ad-field"><label>Default role</label><input id="ad-new-user-drole" type="number" value="0"></div><div class="ad-field" id="ad-new-pass-wrap" style="display:none"><label>Password</label><input type="password" id="ad-new-user-password"></div><div class="ad-field" id="ad-new-pin-wrap" style="display:none"><label>PIN</label><input type="password" id="ad-new-user-pin"></div></div></div><div class="modal-footer"><button type="button" class="btn btn-danger" data-dismiss="modal">Close</button><button type="button" class="btn btn-success" id="ad-create-user">Save User</button></div></div>
